import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';
import ProgressBar from '../components/ProgressBar';

export default function RoadmapPage() {
  const { name } = useParams();
  const navigate = useNavigate();
  const [roadmapPlan, setRoadmapPlan] = useState([]);
  const [domain, setDomain] = useState('');
  const [timeline, setTimeline] = useState('');

  useEffect(() => {
    const rawPlan = localStorage.getItem('roadmapPlan');
    const selectedDomain = localStorage.getItem('selectedDomain') || name || 'blockchain';
    const savedTimeline = localStorage.getItem('timeline') || '3 months';

    if (rawPlan) {
      try {
        const parsedPlan = JSON.parse(rawPlan);
        if (Array.isArray(parsedPlan)) setRoadmapPlan(parsedPlan);
      } catch (e) { console.error(e); }
    }
    setDomain(selectedDomain);
    setTimeline(savedTimeline);
  }, [name]);

  const handleStartLearning = () => navigate('/tasks');
  const getDomainTitle = () => domain.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

  // ✅ CALCULATE DAYS FROM TIMELINE (e.g., "6 months" -> 180 days)
  const totalDays = timeline ? (parseInt(timeline.match(/\d+/)) * 30) : 90;
  
  const completedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");
  const remainingDays = Math.max(totalDays - completedDays.length, 0);
  const completionPercentage = totalDays > 0 ? Math.round((completedDays.length / totalDays) * 100) : 0;

  const getPhaseProgress = (idx, tasks) => {
    let tasksBefore = 0;
    for (let i = 0; i < idx; i++) if (roadmapPlan[i]) tasksBefore += roadmapPlan[i].length;
    const startDay = Math.floor(tasksBefore / 4) + 1;
    const duration = Math.ceil(tasks.length / 4);
    const completed = completedDays.filter(d => d >= startDay && d < startDay + duration).length;
    return Math.min(100, Math.round((completed / duration) * 100));
  };

  return (
    <div className="space-y-8 pb-20">
      <div className="rounded-[2rem] border border-slate-300 bg-white p-8 shadow-lg">
        <h1 className="text-4xl font-bold">{getDomainTitle()} Roadmap</h1>
        <p className="mt-2 text-slate-600">Your personalized {timeline} path with {roadmapPlan.length} phases</p>
        
        <div className="mt-6 flex flex-col gap-6 lg:flex-row">
          <div className="flex-1">
            <p className="text-sm font-bold text-slate-500 uppercase mb-2">Overall Progress</p>
            <ProgressBar label="Roadmap" value={completionPercentage} />
          </div>
          <div className="rounded-3xl bg-teal-50 p-6 border border-teal-100 text-center">
            <p className="text-xs font-bold text-teal-600 uppercase">Timeline</p>
            <p className="text-2xl font-black text-teal-900">{timeline}</p>
          </div>
          <div className="rounded-3xl bg-orange-50 p-6 border border-orange-100 text-center">
            <p className="text-xs font-bold text-orange-600 uppercase">Remaining</p>
            <p className="text-2xl font-black text-orange-900">{remainingDays} / {totalDays} d</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] border p-8 shadow-sm">
        <h2 className="text-2xl font-bold mb-6">📚 Learning Phases</h2>
        {roadmapPlan.length === 0 ? (
          <div className="text-center py-10 text-slate-400">Click "Generate Roadmap" in the Quiz page to view your phases.</div>
        ) : (
          <div className="space-y-6">
            {roadmapPlan.map((phase, idx) => (
              <div key={idx} className={`p-6 rounded-[2rem] border ${getPhaseProgress(idx, phase) === 100 ? 'bg-green-50 border-green-200' : 'bg-slate-50'}`}>
                <div className="flex items-center gap-4 mb-4">
                  <span className="h-10 w-10 flex items-center justify-center rounded-full bg-teal-500 text-white font-bold">{idx + 1}</span>
                  <div className="flex-1">
                    <h3 className="font-bold">Phase {idx + 1}</h3>
                    <ProgressBar label="Progress" value={getPhaseProgress(idx, phase)} />
                  </div>
                </div>
                <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                  {phase.slice(0, 4).map((task, tIdx) => (
                    <div key={tIdx} className="p-4 rounded-2xl bg-white text-sm shadow-sm border border-slate-100">✓ {task}</div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="flex justify-center">
        <Button onClick={handleStartLearning} className="px-10 py-4 text-xl shadow-lg">Start Learning Journey 🚀</Button>
      </div>
    </div>
  );
}
